import React, { useEffect, useRef } from "react";
import classes from "./ProductList.module.css";
import ProductDisplay from "./ProductDisplay";

// todo use later
// type product = {
//   coverImage: string;
//   title: string;
//   course: string;
//   questionsNum: number;
//   id: string;
// };

const ProductsList: React.FC<{ products: number[] }> = (props) => {
  // to delete later and get the image from product
  const imageUrl =
    "data:image/png;base64,";
  const quizIdClicked = "69eefe75464d77b9e5d82348";

  const containerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const elements = containerRef.current?.querySelectorAll(
      `.${classes.reveal}`,
    );

    if (!elements) return;

    const observer = new IntersectionObserver(
      (entries, observer) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add(classes.active);
            observer.unobserve(entry.target);
          }
        });
      },
      {
        threshold: 0.15,
      },
    );

    elements.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, [props.products]);

  return (
    <div ref={containerRef} className={classes["product-list"]}>
      {props.products.map((product, index) => (
        <div className={classes.reveal} key={index}>
          <ProductDisplay
            isLoading={false}
            coverImage={imageUrl}
            course="קורס"
            questionsNum={10}
            title="כותרת"
            productId={quizIdClicked}
          />
        </div>
      ))}
    </div>
  );
};

export default ProductsList;
